export const BATAS_STOK_MENIPIS = 5;
// === stok.js ===
import { BATAS_STOK_MENIPIS } from "./config.js";
export function statusStok(jumlah) {
  if (jumlah === 0) return "habis";
  if (jumlah <= BATAS_STOK_MENIPIS) return "menipis";
  return "aman";
}
// === main.js ===
import { statusStok } from "./stok.js";
const produk = { "Kopi Susu": 12, "Teh Tarik": 0, "Nasi Goreng": 5 };
for (const [nama, jumlah] of Object.entries(produk)) {
  console.log(`${nama}: ${statusStok(jumlah)}`);
}

