// === config.js ===
export const MIN_POIN_BELANJA = 10000;
export const POIN_PER_KELIPATAN = 1;
// === poin.js ===
import { MIN_POIN_BELANJA, POIN_PER_KELIPATAN } from "./config.js";
export function hitungPoin(belanja) {
  return Math.floor(belanja / MIN_POIN_BELANJA) * POIN_PER_KELIPATAN;
}
// === main.js ===
import { hitungPoin } from "./poin.js";
console.log(hitungPoin(35000));
console.log(hitungPoin(9000));
